/**
 * ERC-8021 Transaction Attribution Placeholder
 * 
 * In a real environment, this lib would attach builder codes and
 * attribution codes to on-chain transactions generated by the user.
 */

export const ATTRIBUTION_CODE = '[ATTRIBUTION_CODE]';
export const BUILDER_CODE = 'bc_pnse7ee6'; // Provided by user

export function attachAttribution(txData: any) {
  // Simulate attaching builder code to tx data
  return {
    ...txData,
    builderCode: BUILDER_CODE,
    attributionCode: ATTRIBUTION_CODE,
  };
}

export function generateGMTransaction() {
  return attachAttribution({
    to: '0x0000000000000000000000000000000000000000', // Example
    value: '0',
    data: '0xSayGM'
  });
}
